    {
      "subject": "English cue and sense",
      "conclusion": "Accurate. A napkin is cloth or paper used while eating to wipe the mouth or hands and protect clothing.",
      "material_risk": false,
      "evidence_refs": [
        "https://dictionary.cambridge.org/us/dictionary/english-malaysian/napkin"
      ]
    },
    {
      "subject": "Indonesian answer: serbet",
      "conclusion": "Correct and well aligned. Indonesian serbet is documented as napkin, including in an Indonesian restaurant vocabulary resource.",
      "material_risk": false,
      "evidence_refs": [
        "https://bipa.kemendikdasmen.go.id/filebelajar/116Your_First_Seven_Days_in_Indonesia.pdf",
        "https://glosbe.com/id/en/serbet"
      ]
    },
    {
      "subject": "Malaysian answer: napkin",
      "conclusion": "Correct. Malaysian Malay dictionary sources define napkin as paper or cloth used while eating to wipe the mouth or hands or protect clothing.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/cari1?keyword=napkin",
        "https://dictionary.cambridge.org/us/dictionary/english-malaysian/napkin"
      ]
    },
    {
      "subject": "National split and shared equivalents",
      "conclusion": "The split is not absolute, but it is not materially overstated for this card. Malaysian PRPM lists serbet with an explicit Indonesian label, while napkin is the unmarked Malaysian Malay entry. Tisu is accepted in both varieties for thin absorbent paper, but its meaning is broader than dining napkin.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=73980&keyword=serbet",
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=tisu",
        "https://bipa.kemendikdasmen.go.id/filebelajar/116Your_First_Seven_Days_in_Indonesia.pdf"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "No false-friend contrast is warranted. Malaysian napkin also has a non-dining diaper sense, but the supplied dining cue disambiguates it; this is polysemy, not a cross-variety false friend.",
      "material_risk": false,
